import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: ErrorRetryPage(), debugShowCheckedModeBanner: false));
class ErrorRetryPage extends StatefulWidget { const ErrorRetryPage({super.key}); @override State<ErrorRetryPage> createState() => _ErrorRetryPageState(); }
class _ErrorRetryPageState extends State<ErrorRetryPage> { late Future<Map<String, dynamic>> future; @override void initState() { super.initState(); future = load(); } Future<Map<String, dynamic>> load() async { final r = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts/1')).timeout(const Duration(seconds: 12)); if (r.statusCode != 200) throw Exception('Server returned status ${r.statusCode}'); final data = jsonDecode(r.body); if (data is! Map<String, dynamic>) throw const FormatException('Unexpected API response'); return data; } void retry() => setState(() => future = load());
 @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q10: Error handling and Retry')), body: FutureBuilder<Map<String, dynamic>>(future: future, builder: (context, s) { if (s.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (s.hasError) return Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.wifi_off, size: 48), const SizedBox(height: 12), Text('Unable to fetch data. Check your connection.\n${s.error}', textAlign: TextAlign.center), const SizedBox(height: 12), FilledButton.icon(onPressed: retry, icon: const Icon(Icons.refresh), label: const Text('Retry'))]))); final d = s.data!; return ListTile(title: Text('${d['title']}'), subtitle: Text('${d['body']}')); }));
}
